import{_ as a}from"./chunks/settings-view.5swh14fz.js";import{_ as t,H as s,f as r,i as n}from"./chunks/framework.CSxcEb-0.js";const m=JSON.parse('{"title":"Settings","description":"","frontmatter":{},"headers":[],"relativePath":"guide/settings.md","filePath":"guide/settings.md"}'),o={name:"guide/settings.md"};function i(l,e,d,h,g,c){return s(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p>Open <strong>Settings</strong> from the sidebar. On desktop, section links also appear in the top toolbar when you are on Settings.</p><p><img src="'+a+'" alt="Settings view"></p><h2 id="appearance" tabindex="-1">Appearance <a class="header-anchor" href="#appearance" aria-label="Permalink to &quot;Appearance&quot;">​</a></h2><p><strong>Settings → Theme</strong> (or Appearance):</p><ul><li><strong>Modern Dark / Light</strong> — neutral purple UI</li><li><strong>Phosphor / Variance</strong> — TVA terminal palettes (green or orange on black)</li><li><strong>Dossier</strong> — parchment and rust accents (warm light)</li><li><strong>Frost</strong> — cool slate and teal (calm light, not warm or product-blue)</li><li><strong>Vibe Dark / Light</strong> — monday.com-style product UI</li></ul><p>Optional: scheduled light/dark switching by time of day.</p><h2 id="lists" tabindex="-1">Lists <a class="header-anchor" href="#lists" aria-label="Permalink to &quot;Lists&quot;">​</a></h2><ul><li><strong>Default list</strong> for new tasks</li><li><strong>List colors</strong> — presets, custom hex, <strong>Random color</strong></li><li><strong>Keep list colors across themes</strong> — same hex everywhere, or slight light/dark adjustment at render time</li></ul><p>Colors appear on calendar chips, task rows, filters, and list indicators.</p><h2 id="scheduling-hours" tabindex="-1">Scheduling hours <a class="header-anchor" href="#scheduling-hours" aria-label="Permalink to &quot;Scheduling hours&quot;">​</a></h2><p>Profiles define when tasks <em>can</em> be placed (e.g. Work hours 9–5 weekdays, Personal evenings). Each <strong>list</strong> links to one profile.</p><p>Expand <strong>Manage scheduling hours</strong> to edit day-by-day enable/start/end. Copy first day to all days when setting up a new profile.</p><h2 id="scheduler" tabindex="-1">Scheduler <a class="header-anchor" href="#scheduler" aria-label="Permalink to &quot;Scheduler&quot;">​</a></h2><ul><li><strong>Scheduling horizon</strong> — how many weeks ahead to plan (default 8)</li><li><strong>Schedule breaks</strong> — optional gaps after X minutes of work and/or X tasks (empty space in the plan, not separate “Break” events)</li><li><strong>Reschedule delay</strong>, splittable defaults, buffer before/after events, dependency drag direction, and related toggles</li></ul><h2 id="tasks-and-eisenhower" tabindex="-1">Tasks and Eisenhower <a class="header-anchor" href="#tasks-and-eisenhower" aria-label="Permalink to &quot;Tasks and Eisenhower&quot;">​</a></h2><p>Under <strong>Tasks</strong> (or Theme / task-related toggles):</p><ul><li><strong>Use task priorities</strong> — enables ASAP / High / Normal / Low; ASAP tasks land in the <strong>Do first</strong> quadrant</li><li><strong>Show inbox tasks in Eisenhower matrix</strong> — include inbox/backlog items when using <strong>Matrix</strong> layout on the Tasks view</li></ul><p>See <a href="./tasks">Tasks</a> for quadrant meanings and drag-to-triage behavior.</p><h2 id="calendar-display" tabindex="-1">Calendar display <a class="header-anchor" href="#calendar-display" aria-label="Permalink to &quot;Calendar display&quot;">​</a></h2><p>Week/day/month default, show event end times, skipped tasks on calendar, etc.</p><h2 id="google-calendar" tabindex="-1">Google Calendar <a class="header-anchor" href="#google-calendar" aria-label="Permalink to &quot;Google Calendar&quot;">​</a></h2><p>See the dedicated <a href="./google-calendar">Google Calendar</a> page.</p><h2 id="getting-started-checklist" tabindex="-1">Getting started checklist <a class="header-anchor" href="#getting-started-checklist" aria-label="Permalink to &quot;Getting started checklist&quot;">​</a></h2><p>At the top of Settings, new users see a dismissible checklist linking to the <a href="./../getting-started">getting started tutorial</a>. Dismiss hides it permanently (synced when signed in).</p>',25)])])}const k=t(o,[["render",i]]);export{m as __pageData,k as default};
